/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    SalesTable salesTable = SalesTable::find("700001152");
    CustInvoiceTrans _journalTransaction = CustInvoiceTrans::findRecId(5673099150);
    str tableName = tableId2Name(tableNum(CustInvoiceTrans));
    TAMRebateTable _rebateTable = TAMRebateTable::find("000724");

    TAMRebateQueryBuilder _rebateQueryBuilder = TAMRebateQueryBuilder::newFromRebateTable(_rebateTable);;
    TAMRebateDate _rebateDate;

    select firstonly _rebateDate where _rebateDate.RebateId == "000724";

    //boolean ret = GUPRebateMatchingHelper::checkIfPricingAttributesAreMatchedForSalesByHash(salesTable, _journalTransaction, tableName, _rebateTable);
    boolean ret = GUPRebateMatchingHelper::checkIfPricingAttributesAreMatched(_journalTransaction, _rebateQueryBuilder, _rebateDate, _rebateTable);

    Info(any2Str(ret));

    //Info(any2Str(className2Id("METGUPPricingAttributeSalesTableAsHeaderSourceMETSalesOrderType")));
}
